import{_t as e,it as t,n,rt as r}from"./chunks/framework.Bb3LI7rT.js";var i=JSON.parse(`{"title":"Changelog — Fieldset Spec 1.0","description":"","frontmatter":{},"headers":[],"relativePath":"spec/form-definition/1.0/changelog.md","filePath":"spec/form-definition/1.0/CHANGELOG.md"}`),a={name:`spec/form-definition/1.0/changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<div><h1 id="changelog--fieldset-spec-10" tabindex="-1">Changelog — Fieldset Spec 1.0 <a class="header-anchor" href="#changelog--fieldset-spec-10" aria-label="Permalink to “Changelog — Fieldset Spec 1.0”">​</a></h1><h2 id="editorial--2026-10-22-no-version-change" tabindex="-1">Editorial — 2026-10-22 (no version change) <a class="header-anchor" href="#editorial--2026-10-22-no-version-change" aria-label="Permalink to “Editorial — 2026-10-22 (no version change)”">​</a></h2><ul><li>The README states the meta-schema&#39;s SHA-256 and advises validators to bundle <code>meta-schema.json</code> rather than fetch its <code>$id</code> at runtime; the docs site serves the file at the <code>$id</code> URL. No semantic change: <code>specVersion</code> stays <code>1.0.0</code> and the meta-schema is unchanged.</li></ul><h2 id="rename--2026-10-21-no-version-change" tabindex="-1">Rename — 2026-10-21 (no version change) <a class="header-anchor" href="#rename--2026-10-21-no-version-change" aria-label="Permalink to “Rename — 2026-10-21 (no version change)”">​</a></h2><ul><li>Renamed from &quot;Form Schema Spec 1.0&quot; to &quot;Fieldset Spec 1.0&quot;. The meta-schema <code>$id</code> is now <code>https://beyerenrico.github.io/fieldset/spec/form-definition/1.0/meta-schema.json</code> (was <code>https://localhost/spec/form-definition/1.0/meta-schema.json</code>); the bundled template registry is <code>urn:fieldset:bundled-templates</code>. No semantic change: <code>specVersion</code> stays <code>1.0.0</code>, <code>$schema</code> and <code>source.registry</code> remain pattern-only, so definitions naming the former URIs stay valid.</li></ul><h2 id="100--2026-10-16" tabindex="-1">1.0.0 — 2026-10-16 <a class="header-anchor" href="#100--2026-10-16" aria-label="Permalink to “1.0.0 — 2026-10-16”">​</a></h2><ul><li>Initial release: definition structure, 30 element types, JsonLogic dialect with decimal and date operators, evaluation algorithm, validation error codes, lint rules, versioning and checksum rules.</li><li>Reserved for later features: <code>role</code> (with <code>roles.json</code>), <code>source</code>, <code>i18n</code>, the <code>record</code> type.</li><li>Documented extension: <code>x-import</code>.</li><li>Clarified (same day, before any release): round stability, incremental visibility, normalization errors, repeater <code>minItems</code> on empty lists, rating/attachment/signature/location/hidden checks, JS <code>Number()</code> and <code>==</code> array rules, variadic <code>min</code>/<code>max</code>, operator error handling, lint path and reference rules, data-contract <code>time</code> pattern.</li><li>Hardened (M1 review, before release): restricted ECMAScript pattern subset with fixed semantics and no nested quantifiers (§3.4), 4,096-code-point pattern subject limit, 60-digit decimal limit, 512-level nesting limit and <code>logic_too_deep</code>, calculation order (topological, document order for ties), 254-code-point email limit, finite location numbers, explicit check order, meta-schema URI pattern instead of <code>format: uri</code>, strict asset UUIDs.</li></ul></div>`,1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};